@@ -0 +1 @@
+import { db } from "./store.js"
+import { record } from "./audit.js"
+
+// Erases every stored copy of an account's personal data, in the order set by
+// plans/account-erasure/spec/account-erasure.md.
+export function eraseAccount(user, now = new Date()) {
+  deleteSessions(user.id)
+  db.events = db.events.filter((event) => event.userId !== user.id)
+  deleteTickets(user.id)
+  db.subscribers.delete(user.email)
+  const invoiceIds = minimiseInvoices(user.id, now)
+  unlinkInvoiceAudit(invoiceIds)
+  db.users.delete(user.id)
+  record("account.erased", user.id, {
+    kinds: ["account", "sessions", "events", "tickets", "subscriber", "invoice.email", "invoice.phone", "invoice.userId"],
+    rule: "account-deletion-30d",
+    invoicesMinimised: invoiceIds.length,
+  }, now)
+}
+
+function deleteSessions(userId) {
~ moved 3 lines from src/accounts.js:50
+}
+
+function deleteTickets(userId) {
+  for (const [id, ticket] of db.tickets) {
+    if (ticket.userId === userId) db.tickets.delete(id)
+  }
+}
+
+// Keeps what tax law requires (ADR 0002); drops the email, phone and account link.
+function minimiseInvoices(userId, now) {
+  const ids = []
+  for (const invoice of db.invoices.values()) {
+    if (invoice.userId !== userId) continue
+    const { name, address, taxId } = invoice.billing
+    invoice.billing = { name, address, taxId }
+    invoice.userId = null
+    invoice.erasedAt = now.toISOString()
+    ids.push(invoice.id)
+  }
+  return ids
+}
+
+// invoice.issued entries copy the invoice→account link that minimisation removes (ADR 0003).
+function unlinkInvoiceAudit(invoiceIds) {
+  for (const entry of db.audit) {
+    if (entry.action === "invoice.issued" && invoiceIds.includes(entry.subject)) delete entry.detail.userId
+  }
+}
